"""One-off: turns Louisiana's 25_m13_watch.js into California's. Run once: python3 -I patch_m13.py"""
import os
P = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'atlas', 'src', '25_m13_watch.js')
t = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global t
    assert t.count(a) == n, (t.count(a), a[:70])
    t = t.replace(a, b)

rep("desc: 'What the mapped roofing companies are doing: ads on Meta and Google, free, insurance and warranty claims, Spanish, coverage by line, with library links and an API bridge',",
    "desc: 'What roofing companies say and where they buy: the licence field by city and county, a watchlist you build, ads on Meta and Google, claims screened by the California rule pack, with library links and an API bridge',")
rep("eyebrow: 'Module 13 · Competitor Watch · ledger, library links, API bridge'", "eyebrow: 'Module 13 · Competitor Watch · licence field, watchlist, ledger, compliance bench'")
i = t.index("dek: 'The field in module 07"); j = t.index("meta: [`<b>Companies</b>")
t = t[:i] + "dek: `The field in module 07 is where the roofing companies are; this module is what they say and where they buy. California has no public ranked list of roofers, so the atlas ships only the ${N(WATCH.ROSTER.length)} companies named in its evidence and measures the field itself from Contractors State License Board C-39 licences and Census establishment counts by city and county. You add the companies you meet in your market to the watchlist; the module keeps a ledger of what they publish (ads seen in the Meta Ad Library and the Google Ads Transparency Center, claims on their sites, yard signs, door hangers, truck wraps, television spots, pages in Spanish and other languages, review counts), screens every claim against the California rule pack of the Compliance Satchel, and turns the ledger into share of voice, coverage by service line and a sweep schedule.`,\n      " + t[j:]
rep("meta: [`<b>Companies</b> ${N(WATCH.COMPANIES.length)} tracked`,", "meta: [`<b>Field</b> ${N(WATCH.FIELD.state.lic)} active C-39 licences in ${N(WATCH.FIELD.cities.length)} cities`, `<b>Watchlist</b> ${N(WATCH.COMPANIES.length)} companies, yours to extend`,")
rep("'<b>Lint</b> every claim screened by the Satchel rule pack'],", "'<b>Lint</b> every claim screened by the California rule pack'],")
rep("{ id: 'w13Sweep', label: '↓ Sweep checklist' },", "{ id: 'w13Sweep', label: '↓ Sweep checklist' }, { id: 'w13FieldCsv', label: '↓ Licence field CSV' },")
rep("Every entry is something a person saw and logged, or a library record pulled through the API, with its date.",
    "The licence counts are the board's roll of active C-39 Roofing licences by mailing address: where a firm is, not where it works, and about two licences for every roofing employer in the Census counts, because many licensees have no payroll. The watchlist is not a ranking: no public source measures a California roofer's size. Every ledger entry is something a person saw and logged, or a library record pulled through the API, with its date.")
