    "<div class=\"tscroll\" id=\"w13Tbl\"></div>"
    "<div class=\"dsec\">Add a company to the watchlist</div><div class=\"plan\"><div class=\"f\"><label class=\"fl\" for=\"w13AN\">Company name</label><input type=\"text\" id=\"w13AN\" placeholder=\"as it advertises\"></div><div class=\"f\"><label class=\"fl\" for=\"w13AD\">Website</label><input type=\"text\" id=\"w13AD\" placeholder=\"example.com\"></div><div class=\"f\"><label class=\"fl\" for=\"w13AH\">City</label><input type=\"text\" id=\"w13AH\" list=\"w13ACities\"><datalist id=\"w13ACities\"></datalist></div><div class=\"f\"><label class=\"fl\" for=\"w13AT\">Reach</label><select id=\"w13AT\"><option>local</option><option>regional</option><option>statewide</option><option>national</option></select></div><div class=\"f\"><label class=\"fl\" for=\"w13AL\">CSLB licence number</label><input type=\"text\" id=\"w13AL\" inputmode=\"numeric\" placeholder=\"from the ad or the truck\"></div><div class=\"f wide\"><span class=\"fl\">Lines it markets</span><div id=\"w13ALines\" style=\"display:flex;gap:8px;flex-wrap:wrap\"></div></div></div><div style=\"margin-top:8px\"><button class=\"btn\" id=\"w13AddCo\">Add to the watchlist</button> <span class=\"mini\">Kept in this browser with the ledger; it travels in the JSON export.</span></div>"
