    "      ${card('Compliance bench: test ad text against the California rule pack', 'Paste what a competitor published, or try the samples. The eight samples are invented for this atlas: no company published them. A hit is intelligence about the claim, not a finding about a company.', `<div class=\"plan\"><div class=\"f wide\"><label class=\"fl\" for=\"w13BT\">Ad or claim text</label><textarea id=\"w13BT\" style=\"min-height:70px\" placeholder=\"paste the text as published\"></textarea></div><div class=\"f\"><label class=\"fl\" for=\"w13BP\">Where it ran</label><select id=\"w13BP\">${Object.entries(WATCH.PLATFORMS).map(([k, l]) => `<option value=\"${k}\">${esc(l)}</option>`).join('')}</select></div></div><div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:8px\"><button class=\"btn\" id=\"w13BRun\">Screen it</button><button class=\"btn ghost\" id=\"w13BLog\">Log it for the selected company</button></div><div id=\"w13BOut\" style=\"margin-top:10px\"></div><div class=\"dsec\">Sample ads (invented)</div><div id=\"w13BSam\"></div>`, 'mt')}\n"
