# field tables, bench and add form, before refresh()
rep("    function refresh() { kpis(); digest(); table(); firm(); charts(); plan(); }",
r"""    /* ---------- the field by place ---------- */
    const fst = { reg: null, q: '' };
    function field() {
      const F = W.FIELD; const rows = fst.reg == null ? F.regions.map(r => Object.assign({ id: 'r' + r.k, nm: r.name, sub: N(r.n) + ' counties' }, r)) : F.counties.filter(c => c.reg === fst.reg).map(c => Object.assign({ id: 'c' + c.fips, nm: c.name + ' County', sub: '' }, c));
      dataTable($('#w13Fld', root), [{ k: 'nm', h: fst.reg == null ? 'Region' : 'County', l: 1, f: (v, r) => `<b>${esc(v)}</b>${r.sub ? ' <span class="mini">' + esc(r.sub) + '</span>' : ''}` }, { k: 'lic', h: 'C-39 licences', f: v => N(v) }, { k: 'per10k', h: 'Per 10,000 residents', f: v => D(v, 2) }, { k: 'cbp', h: 'Employers (CBP)', f: v => v == null ? '<span class="mini">withheld</span>' : N(v), t: 'Roofing contractor establishments with employees, County Business Patterns; a region sums the counties the Census publishes' }, { k: 'roofsPer', h: 'One unit roofs per licence', f: v => N(v) }, { k: 'feesPer', h: 'Pool per licence', f: v => MM(v), t: 'Gross profit pool (model) divided by active licences' }], rows, { sortKey: 'lic', id: r => r.id, onClick: id => { if (String(id)[0] === 'r') { fst.reg = +String(id).slice(1); field(); } } });
      const thin = F.regions.filter(r => r.lic > 0).slice().sort((a, b) => b.roofsPer - a.roofsPer)[0], thick = F.regions.filter(r => r.lic > 0).slice().sort((a, b) => a.roofsPer - b.roofsPer)[0];
      $('#w13FldN', root).innerHTML = (fst.reg != null ? `<button class="ibtn" id="w13FldBack">← All regions</button> ` : '') + (thin && thick ? `${esc(thin.name)} has the most one unit roofs behind each licence (${N(thin.roofsPer)}) and ${esc(thick.name)} the fewest (${N(thick.roofsPer)}). A licence is counted where its holder gets mail, so a firm that works three counties counts once, at home.` : 'No licence counts in this build of the data.') + ` ${G('A')}`;
      const b = $('#w13FldBack', root); if (b) b.onclick = () => { fst.reg = null; field(); };
    }
    function cityTbl() {
      const q = fst.q; const rows = W.FIELD.cities.filter(c => !q || (c.city + ' ' + c.county).toLowerCase().includes(q)).map(c => Object.assign({ regn: REGN[c.reg] || '' }, c));
      dataTable($('#w13Cty', root), [{ k: 'city', h: 'City', l: 1, f: v => `<b>${esc(v)}</b>` }, { k: 'county', h: 'County', l: 1 }, { k: 'regn', h: 'Region', l: 1 }, { k: 'lic', h: 'Active C-39', f: v => N(v) }, { k: 'lic_all', h: 'On the roll', f: v => N(v), t: 'Including suspended licences' }, { k: 'lib', h: 'Libraries', l: 1, v: r => r.city, f: v => `<a href="${esc(W.LINKS.metaKw('roofing ' + v))}" target="_blank" rel="noopener">Meta ↗</a> · <a href="${esc(W.LINKS.gSearch('', v))}" target="_blank" rel="noopener">Search ↗</a>` }], rows, { sortKey: 'lic', limit: 60 });
      if (!rows.length) $('#w13Cty', root).innerHTML = '<p class="mini" style="padding:10px">No city matches, or the licence table is not in this build of the data.</p>';
    }
    /* ---------- compliance bench ---------- */
    const sevCls = s => s === 'block' ? 'bad' : s === 'warn' ? 'warn' : '';
    const hitsHTML = hits => hits.length ? hits.map(h => `<div class="asset ${sevCls(h.sev)}"><b>${esc(h.id)}</b> · ${esc(h.name)} <span class="mini">${esc(h.sev)}${h.cite ? ' · ' + esc(h.cite) : ''}</span>${h.ev ? `<div class="mini">Matched: ${esc(String(h.ev).slice(0, 160))}</div>` : ''}${h.fix ? `<span class="why">${esc(h.fix)}</span>` : ''}</div>`).join('') : '<p class="mini">No rule of the pack is tripped by this text. That is not clearance: the pack screens wording, not the facts behind it.</p>';
    function bench() {
      $('#w13BSam', root).innerHTML = W.SAMPLES.map(s => { const hits = W.lintText(s.text, s.platform); return `<div class="asset ${hits.some(h => h.sev === 'block') ? 'bad' : hits.length ? 'warn' : ''}"><span class="cnt">${N(hits.length)}</span><b>${esc(s.label)}</b> <span class="pill">invented sample</span> <span class="mini">${esc(W.PLATFORMS[s.platform] || s.platform)}</span><div>${esc(s.text)}</div><span class="why">${hits.length ? 'Rules: ' + esc(hits.map(h => h.id + ' ' + h.name).join('; ')) : 'No rule tripped.'}</span><div style="margin-top:4px"><button class="btn ghost sm" data-sam="${s.id}">Open in the bench</button></div></div>`; }).join('');
      $$('[data-sam]', root).forEach(b => b.onclick = () => { const s = W.SAMPLES.find(x => x.id === b.dataset.sam); $('#w13BT', root).value = s.text; $('#w13BP', root).value = s.platform; runBench(); });
    }
    function runBench() { const txt = $('#w13BT', root).value; if (!txt.trim()) { $('#w13BOut', root).innerHTML = '<p class="mini">Paste some text first.</p>'; return; } const hits = W.lintText(txt, $('#w13BP', root).value); $('#w13BOut', root).innerHTML = `<div class="mini" style="margin-bottom:6px">${N(hits.length)} rules tripped · line read as ${esc(W.inferLine(txt) ? SLM.lineName(W.inferLine(txt)) : 'not specific')} · claim type ${esc(W.OFFERS[W.inferOffer(txt)] || 'none')} · hook ${esc(W.inferHook(txt))}</div>` + hitsHTML(hits); }
    $('#w13BRun', root).onclick = runBench;
    $('#w13BLog', root).onclick = () => { const txt = $('#w13BT', root).value.trim(); if (!txt) { toast('Paste the text first'); return; } if (!st.sel || !W.CI[st.sel]) { toast('Select a company in the watchlist first'); return; } if (W.SAMPLES.some(s => s.text === txt)) { toast('That is an invented sample; it is not logged'); return; } const p = $('#w13BP', root).value; W.add({ comp: st.sel, compName: W.CI[st.sel].name, kind: p === 'site' ? 'claim' : 'ad', platform: p, status: 'unknown', text: txt, line: W.inferLine(txt), hook: W.inferHook(txt), offer: { type: W.inferOffer(txt), text: '' } }); toast('Logged'); refresh(); };
    /* ---------- add a company ---------- */
    $('#w13ACities', root).innerHTML = W.FIELD.cities.slice(0, 400).map(c => `<option value="${esc(c.city)}">`).join('');
    $('#w13ALines', root).innerHTML = PL.map(l => `<label class="chk"><input type="checkbox" value="${l.key}"> ${esc(l.short)}</label>`).join('');
    $('#w13AddCo', root).onclick = () => { const name = $('#w13AN', root).value.trim(); if (!name) { toast('Give the company a name'); return; } const c = W.addCompany({ name, domain: $('#w13AD', root).value.trim(), hq: $('#w13AH', root).value.trim(), tier: $('#w13AT', root).value, lic_no: $('#w13AL', root).value, lines: $$('#w13ALines input:checked', root).map(i => i.value) }); if (!c) return; ['#w13AN', '#w13AD', '#w13AH', '#w13AL'].forEach(id => { $(id, root).value = ''; }); $$('#w13ALines input', root).forEach(i => { i.checked = false; }); st.sel = c.key; st.edit = null; toast('Added to the watchlist'); refresh(); };
    $('#w13CQ', root).addEventListener('input', debounce(e => { fst.q = e.target.value.trim().toLowerCase(); cityTbl(); }, 200));
    $('#w13FieldCsv', root).onclick = () => saveFile(`california-roofing-licence-field_${W.today()}.csv`, toCSV(['level', 'name', 'county', 'region', 'active_c39_licences', 'c39_on_roll', 'licences_per_10k_residents', 'roofing_employers_cbp', 'one_unit_roofs', 'gross_profit_pool_model'], W.FIELD.regions.map(r => ['region', r.name, '', r.name, r.lic, '', r.per10k == null ? '' : +D(r.per10k, 3), r.cbp, Math.round(r.roofs), Math.round(r.fees)]).concat(W.FIELD.counties.map(c => ['county', c.name, c.name, REGN[c.reg] || '', c.lic, c.lic_all == null ? '' : c.lic_all, c.per10k == null ? '' : +D(c.per10k, 3), c.cbp == null ? '' : c.cbp, Math.round(c.roofs), Math.round(c.fees)])).concat(W.FIELD.cities.map(c => ['city', c.city, c.county, REGN[c.reg] || '', c.lic, c.lic_all, '', '', '', ''])), 'California Roofer Guru, module 13. Active C-39 Roofing licences by mailing address (Contractors State License Board licence master file); roofing employers from County Business Patterns, blank where withheld. Counts say where licensees are, not how large they are.'));
    function refresh() { kpis(); digest(); table(); firm(); charts(); plan(); }
    field(); cityTbl(); bench();""")
rep("    BUS.on('theme', () => charts()); BUS.on('slm', () => { if (!root.hidden) charts(); });", "    BUS.on('theme', () => charts()); BUS.on('slm', () => { if (!root.hidden) { charts(); field(); } });")
